//! Boat/water catalogue: schema, loading and validation.
//!
//! The asset is generated by the extraction pipeline from the disc.
//! Every value here is source-derived; the loader re-checks the two semantic
//! digests (collision plane and point rows) instead of trusting the file.
//! Strings and slices are borrowed from the parsed JSON owner; nothing
//! allocates after load.
const std = @import("std");
const validation = @import("validation");

pub const schema = "suikoden-campaign-boat-water/1";
pub const id = "region_j_region_9";
pub const max_json_bytes = 1024 * 1024;
pub const max_points = 64;
pub const max_boards = 8;
pub const max_terms = 8;
pub const max_clauses = 4;
pub const max_anchors = 64;
pub const max_limits = 16;
pub const water_width = 160;
pub const water_height = 120;
pub const water_threshold = 133;
pub const passable_max = 21;
pub const special_first = 303;
pub const special_last = 310;
pub const scenario_base = 400;

pub const Source = struct {
    file: []const u8,
    lba: u32,
    size: u32,
    sha256: []const u8,
};
pub const Sources = struct {
    main: Source,
    water: Source,
    boards: []const Source,
};
pub const Probe = struct {
    x: i32,
    y: i32,
    codes: [4]u16,
};
pub const Water = struct {
    width: u16,
    height: u16,
    threshold: u16,
    codes_sha256: []const u8,
    probe: Probe,
    codes: []const u16,
};
pub const Point = struct {
    index: u16,
    id: []const u8,
    kind: u8,
    x: i32,
    y: i32,
    room: u8,
    spawn_x: u16,
    spawn_y: u16,
    destination: ?[]const u8,
};
pub const Points = struct {
    points_sha256: []const u8,
    rows: []const Point,
};
pub const Clause = struct {
    tier: ?u8 = null,
    story_index: u8,
    mask: u8,
    present: bool,
};
pub const PointRule = struct {
    kind: u8,
    handler: []const u8,
    always: ?bool = null,
    clauses: []const Clause,
};
pub const TermKind = enum {
    story_mask_set,
    story_mask_clear,
    hero_x_range,
    hero_y_range,
    input_mask,
};
pub const Term = struct {
    kind: TermKind,
    index: u8 = 0,
    mask: u8 = 0,
    lower: u8 = 0,
    upper: u8 = 0,
    input: u16 = 0,
};
pub const Fragment = struct {
    offset: u32,
    bytes: []const u8,
    mode_operand: u8,
    mode_value: u8,
    wait_format: u8,
    coord_opcode: u8,
    x: i32,
    y: i32,
};
pub const Outcome = struct {
    world_mode: ?u8,
    vessel: bool,
    camera_x: i32 = 0,
    camera_y: i32 = 0,
};
pub const SlotGuard = struct {
    normal: u8,
    upgraded: u8,
};
pub const Board = struct {
    id: []const u8,
    file: []const u8,
    sha256: []const u8,
    room: u8,
    entry: u8,
    record_offset: u32,
    stream_offset: u32,
    predicate: []const Term,
    pre_choice_mode_write: bool,
    fragment: Fragment,
    board: Outcome,
    decline: Outcome,
    sprite_slot: SlotGuard,
};
pub const ModeValue = struct {
    operand: u8,
    value: u8,
    name: []const u8,
};
pub const FieldRequest = struct {
    address: []const u8,
    installs: []const u8,
    game_state_flag_1d5e: u8,
    game_state_flag_1d5f: u8,
};
pub const Cleanup = struct {
    address: []const u8,
    world_mode: u8,
    selector: u8,
};
pub const Mode = struct {
    address: []const u8,
    values: []const ModeValue,
    selector_address: []const u8,
    foot_selector: u8,
    field_request: FieldRequest,
    cleanup: Cleanup,
};
pub const Upgrade = struct {
    address: []const u8,
    mask: u8,
};
pub const WaterGuard = struct {
    passable_max: u16,
    special_first: u16,
    special_last: u16,
};
pub const Maelstrom = struct {
    stages: []const []const u8,
    predicate: []const u8,
    request: []const u8,
    producer: []const u8,
    accept_branch: []const u8,
    request_branch: []const u8,
};
pub const Facing = struct {
    saved_field_facing_address: []const u8,
    domain: u8,
    teardown: []const u8,
    sprite_constructor: []const u8,
    hero_constructor: []const u8,
};
pub const MaskEntry = struct {
    index: u8,
    mask: u16,
};
pub const Initial = struct {
    movement_heading: u8,
    movement_heading_name: []const u8,
    sprite_prior_heading_byte: u8,
};
pub const Guards = struct {
    upgrade: Upgrade,
    sprite_slot: SlotGuard,
    water: WaterGuard,
    maelstrom: Maelstrom,
    facing: Facing,
    scenario_base: u16,
    input_mask_table: []const MaskEntry,
    initial: Initial,
};
pub const Anchor = struct {
    address: []const u8,
    word: []const u8,
    meaning: []const u8,
};
pub const Packet = struct {
    schema: []const u8,
    id: []const u8,
    region: u8,
    sources: Sources,
    water: Water,
    points: Points,
    point_rules: []const PointRule,
    boards: []const Board,
    mode: Mode,
    guards: Guards,
    anchors: []const Anchor,
    limits: []const []const u8,

    pub fn board(self: Packet, board_id: []const u8) ?Board {
        for (self.boards) |entry| if (std.mem.eql(u8, entry.id, board_id)) return entry;
        return null;
    }

    pub fn pointRule(self: Packet, kind: u8) ?PointRule {
        for (self.point_rules) |rule| if (rule.kind == kind) return rule;
        return null;
    }

    /// `true` when any clause is satisfied (the source ORs them).  An unknown
    /// kind or the table terminator never dispatches.
    pub fn pointKindMatches(self: Packet, kind: u8, tier: u8, story: *const [240]u8) bool {
        const rule = self.pointRule(kind) orelse return false;
        if (rule.always) |value| return value;
        for (rule.clauses) |clause| {
            if (clause.tier) |required| if (required != tier) continue;
            const present = story[clause.story_index] & clause.mask != 0;
            if (present == clause.present) return true;
        }
        return false;
    }
};

fn isHex64(text: []const u8) bool {
    return validation.isHex64(text);
}

fn validIdentifier(text: []const u8) bool {
    return validation.isAsciiId(text, 96, "_.-");
}

fn validPath(text: []const u8) bool {
    return validation.isAsciiId(text, 128, "_.-/:");
}

fn decodeHexU32(text: []const u8) ?u32 {
    if (text.len != 10 or !std.mem.startsWith(u8, text, "0x")) return null;
    return std.fmt.parseInt(u32, text[2..], 16) catch null;
}

fn waterDigest(codes: []const u16) [32]u8 {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var encoded: [2]u8 = undefined;
    for (codes) |code| {
        std.mem.writeInt(u16, &encoded, code, .little);
        hasher.update(&encoded);
    }
    var digest: [32]u8 = undefined;
    hasher.final(&digest);
    return digest;
}

fn pointsDigest(rows: []const Point) [32]u8 {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var record: [14]u8 = undefined;
    for (rows) |point| {
        hasher.update(point.id);
        hasher.update(&.{0});
        record[0] = point.kind;
        std.mem.writeInt(i32, record[1..5], point.x, .little);
        std.mem.writeInt(i32, record[5..9], point.y, .little);
        record[9] = point.room;
        std.mem.writeInt(u16, record[10..12], point.spawn_x, .little);
        std.mem.writeInt(u16, record[12..14], point.spawn_y, .little);
        hasher.update(&record);
        hasher.update(point.destination orelse "");
        hasher.update(&.{0});
    }
    var digest: [32]u8 = undefined;
    hasher.final(&digest);
    return digest;
}

pub fn validate(packet: Packet) !void {
    if (!std.mem.eql(u8, packet.schema, schema) or !std.mem.eql(u8, packet.id, id) or packet.region != 9) return error.UnsupportedBoatCatalogue;
    if (!validPath(packet.sources.main.file) or !isHex64(packet.sources.main.sha256)) return error.InvalidBoatSource;
    if (!std.mem.eql(u8, packet.sources.main.file, "MAIN.EXE")) return error.UnsupportedBoatMainIdentity;
    if (!isHex64(packet.sources.water.sha256) or packet.sources.water.size != 97654) return error.InvalidBoatSource;
    if (packet.sources.boards.len == 0 or packet.sources.boards.len > max_boards) return error.InvalidBoatSource;
    for (packet.sources.boards) |source| {
        if (!validPath(source.file) or !isHex64(source.sha256)) return error.InvalidBoatSource;
    }
    const water = packet.water;
    if (water.width != water_width or water.height != water_height or water.threshold != water_threshold) return error.InvalidBoatWater;
    if (water.codes.len != water_width * water_height) return error.InvalidBoatWater;
    const plane: [64]u8 = std.fmt.bytesToHex(waterDigest(water.codes), .lower);
    if (!std.mem.eql(u8, water.codes_sha256, &plane)) return error.BoatWaterDigestMismatch;
    if (water.probe.x < 0 or water.probe.y < 0 or water.probe.x >= water.width or water.probe.y >= water.height) return error.InvalidBoatWater;
    const deltas = [4][2]i32{ .{ 0, -1 }, .{ 1, 0 }, .{ 0, 1 }, .{ -1, 0 } };
    for (deltas, 0..) |delta, index| {
        const x = water.probe.x + 10 + delta[0];
        const y = water.probe.y + 8 + delta[1];
        if (x < 0 or y < 0 or x >= water.width or y >= water.height) return error.InvalidBoatWater;
        const code = water.codes[@intCast(y * @as(i32, water.width) + x)];
        if (code != water.probe.codes[index]) return error.BoatProbeMismatch;
    }
    if (packet.points.rows.len == 0 or packet.points.rows.len > max_points) return error.InvalidBoatPoints;
    const point_plane = std.fmt.bytesToHex(pointsDigest(packet.points.rows), .lower);
    if (!std.mem.eql(u8, packet.points.points_sha256, &point_plane)) return error.BoatPointDigestMismatch;
    for (packet.points.rows, 0..) |point, index| {
        if (!validIdentifier(point.id) or point.kind > 12) return error.InvalidBoatPoint;
        if (point.x < 0 or point.y < 0 or point.x >= water.width or point.y >= water.height) return error.InvalidBoatPoint;
        if (point.spawn_x > 2047 or point.spawn_y > 2047) return error.InvalidBoatPoint;
        if (point.destination) |destination| if (!validIdentifier(destination)) return error.InvalidBoatPoint;
        for (packet.points.rows[0..index]) |other| if (std.mem.eql(u8, other.id, point.id)) return error.DuplicateBoatPoint;
    }
    if (packet.point_rules.len == 0 or packet.point_rules.len > 12) return error.InvalidBoatPointRule;
    var previous_kind: i16 = -1;
    for (packet.point_rules) |rule| {
        if (rule.kind > 12 or rule.kind <= previous_kind) return error.InvalidBoatPointRule;
        previous_kind = rule.kind;
        if (decodeHexU32(rule.handler) == null) return error.InvalidBoatPointRule;
        if (rule.always) |_| {
            if (rule.clauses.len != 0) return error.InvalidBoatPointRule;
        } else {
            if (rule.clauses.len == 0 or rule.clauses.len > max_clauses) return error.InvalidBoatPointRule;
            for (rule.clauses) |clause| {
                if (clause.tier) |tier| if (tier > 4) return error.InvalidBoatPointRule;
                if (clause.story_index >= 240 or clause.mask == 0) return error.InvalidBoatPointRule;
            }
        }
    }
    if (packet.boards.len == 0 or packet.boards.len > max_boards) return error.InvalidBoatBoard;
    for (packet.boards, 0..) |entry, index| {
        if (!validIdentifier(entry.id) or !validPath(entry.file) or !isHex64(entry.sha256)) return error.InvalidBoatBoard;
        if (entry.predicate.len == 0 or entry.predicate.len > max_terms) return error.InvalidBoatBoard;
        if (entry.fragment.mode_operand != 12 or entry.fragment.mode_value != 1) return error.InvalidBoatBoard;
        if (entry.fragment.wait_format != 0xFB or entry.fragment.coord_opcode != 9) return error.InvalidBoatBoard;
        if (entry.fragment.offset == 0 or entry.fragment.bytes.len != 14) return error.InvalidBoatBoard;
        for (entry.fragment.bytes) |byte| if (!std.ascii.isHex(byte)) return error.InvalidBoatBoard;
        if (!entry.board.vessel or entry.decline.vessel) return error.InvalidBoatBoard;
        if (entry.board.world_mode == null or entry.board.world_mode.? != 1) return error.InvalidBoatBoard;
        if (entry.sprite_slot.normal != 2 or entry.sprite_slot.upgraded != 4) return error.InvalidBoatBoard;
        if (entry.board.camera_x < 0 or entry.board.camera_y < 0 or entry.board.camera_x >= water.width or entry.board.camera_y >= water.height) return error.InvalidBoatBoard;
        if (entry.fragment.x != entry.board.camera_x or entry.fragment.y != entry.board.camera_y) return error.InvalidBoatBoard;
        for (entry.predicate) |term| switch (term.kind) {
            .story_mask_set, .story_mask_clear => {
                if (term.index >= 240 or term.mask == 0) return error.InvalidBoatBoard;
            },
            .hero_x_range, .hero_y_range => if (term.lower > term.upper) return error.InvalidBoatBoard,
            .input_mask => if (term.input == 0 or (term.input & 0xF000) != term.input) return error.InvalidBoatBoard,
        };
        for (packet.boards[0..index]) |other| if (std.mem.eql(u8, other.id, entry.id)) return error.DuplicateBoatBoard;
    }
    if (packet.mode.values.len != 3) return error.InvalidBoatMode;
    for (packet.mode.values, 0..) |value, index| {
        if (value.operand != 11 + index or value.value != index) return error.InvalidBoatMode;
    }
    if (packet.mode.foot_selector != 255 or packet.mode.cleanup.world_mode != 0 or packet.mode.cleanup.selector != 255) return error.InvalidBoatMode;
    const guards = packet.guards;
    if (guards.upgrade.mask != 0x20) return error.InvalidBoatGuard;
    if (guards.water.passable_max != passable_max or guards.water.special_first != special_first or guards.water.special_last != special_last) return error.InvalidBoatGuard;
    if (guards.facing.domain != 4) return error.InvalidBoatGuard;
    if (guards.scenario_base != scenario_base) return error.InvalidBoatGuard;
    if (guards.initial.movement_heading != 1 or !std.mem.eql(u8, guards.initial.movement_heading_name, "east")) return error.InvalidBoatGuard;
    if (guards.input_mask_table.len != 4) return error.InvalidBoatGuard;
    for (guards.input_mask_table, 0..) |mask, index| {
        if (mask.index != index or mask.mask != @as(u16, 0x1000) << @as(u4, @intCast(index))) return error.InvalidBoatGuard;
    }
    if (guards.maelstrom.stages.len != 5) return error.InvalidBoatGuard;
    if (packet.anchors.len == 0 or packet.anchors.len > max_anchors) return error.InvalidBoatAnchor;
    for (packet.anchors) |anchor| {
        if (decodeHexU32(anchor.address) == null) return error.InvalidBoatAnchor;
        const value = decodeHexU32(anchor.word) orelse return error.InvalidBoatAnchor;
        if (value == 0) return error.InvalidBoatAnchor;
        if (anchor.meaning.len == 0) return error.InvalidBoatAnchor;
    }
    if (packet.limits.len == 0 or packet.limits.len > max_limits) return error.InvalidBoatLimit;
}

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Packet) {
    if (bytes.len > max_json_bytes) return error.BoatCatalogueTooLarge;
    const parsed = try std.json.parseFromSlice(Packet, allocator, bytes, .{ .allocate = .alloc_always });
    errdefer parsed.deinit();
    try validate(parsed.value);
    return parsed;
}
